// Allocate 16kb stack with 16-byte alignment
.section .bss
.align 16
stack_bottom:
    .skip 16384 // 16kb stack
stack_top:

// Entry point to the kernel
.section .text
.global _start
.type _start, @function
_start:
    // multiboot specifies that we boot into 32-bit protected mode
    // Keep IRQs masked until Rust has installed the descriptor tables and PIC.
    cli
    // Multiboot leaves DF undefined; the i686 Rust/C ABI requires it clear.
    cld

    // setup the stack
    mov $stack_top, %esp

    // Provide 16-byte pre-CALL alignment (target data-layout S128), even though
    // the current soft-float i686-none compiler may use only 4-byte alignment.
    // Reserve 8 bytes before the two 4-byte args; callee entry ESP is 12 mod 16.
    sub $8, %esp

    // push multiboot info as args to kernel_main
    // reversed calling order: last argument first
    push %ebx // addr of multiboot info struct
    push %eax // multiboot magic number

    // enter the kernel
    call kernel_main

//! PIT channel 0 system timer. Mode 1 (rate generator), 100 Hz from the
//! 1193182 Hz base clock. Pure divisor math is host-testable; port I/O is
//! gated out under test builds.

use crate::io::ports::lockfree_outb;

pub const PIT_BASE_HZ: u32 = 1_193_182;
pub const TIMER_HZ: u32 = 100;

/// PIT divisor for a target frequency. Returns None if the divisor does not
/// fit the 16-bit counter (PIT max divisor is 65535).
pub fn pit_divisor(hz: u32) -> Option<u16> {
    if hz == 0 {
        return None;
    }
    let d = PIT_BASE_HZ / hz;
    if d == 0 || d > 65535 {
        return None;
    }
    Some(d as u16)
}

pub fn init() {
    #[cfg(test)]
    return;
    #[allow(unreachable_code)]
    unsafe {
        let div = pit_divisor(TIMER_HZ).expect("valid PIT divisor");
        lockfree_outb(0x43, 0x36); // cmd: channel 0, lolo, mode 1, binary
        lockfree_outb(0x40, div as u8);
        lockfree_outb(0x40, (div >> 8) as u8);
    }
}

/// Monotonic tick counter, incremented by the timer ISR (IRQ0 / vector 0x20).
static TICKS: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);

pub fn isr_timer() {
    TICKS.fetch_add(1, core::sync::atomic::Ordering::Relaxed);
}

pub fn ticks() -> u32 {
    TICKS.load(core::sync::atomic::Ordering::Relaxed)
}

pub fn uptime_secs() -> u32 {
    ticks() / TIMER_HZ
}

