/// Called once with CLI after stack ownership/mapping preparation and unlock.
/// False is a pre-publication refusal only. Any post-LGDT discrepancy diverges
/// through the bounded assembly terminal; no rollback, retry or busy clearing.
pub(crate) fn install(directory: u32) -> bool {
    install_policy::<false>(directory)
}

/// F5-only failure transport. The one-shot descriptor/TSS operation is shared
/// unchanged, but a post-publication discrepancy returns only to F5's divergent
/// FAIL terminal. Attempt remains consumed: no rollback, retry or busy clearing.
pub(crate) fn install_f5(directory: u32) -> bool {
    install_policy::<true>(directory)
}

fn install_policy<const F5: bool>(directory: u32) -> bool {
    if !cpu_profile(directory) || !selectors_valid() || !context_valid() {
        return false;
    }
    unsafe {
        if read_volatile(addr_of!(f3_context.attempt)) != 0 {
            return false;
        }
        write_volatile(addr_of_mut!(f3_context.attempt), 1);
    }
    if task_register() != 0 {
        return false;
    }
    unsafe {
        write_volatile(addr_of_mut!(f3_context.normal), normal_state());
        write_volatile(
            addr_of_mut!(f3_context.emergency),
            emergency_state(directory),
        );
        let entries = addr_of_mut!(f3_context.entries).cast::<u64>();
        write_volatile(entries, 0);
        write_volatile(entries.add(1), KERNEL_CODE);
        write_volatile(entries.add(2), KERNEL_DATA);
        write_volatile(
            entries.add(3),
            descriptor(addr_of!(f3_context.normal) as u32, 0x89),
        );
        write_volatile(
            entries.add(4),
            descriptor(addr_of!(f3_context.emergency) as u32, 0x89),
        );
        let gdtr = Gdtr {
            limit: 39,
            base: entries as u32,
        };
        asm!(
            "cli",
            "lgdt ({gdt})",
            "jmp $0x08, $2f",
            "2:",
            "mov $0x10, %ax",
            "mov %ax, %ds",
            "mov %ax, %es",
            "mov %ax, %fs",
            "mov %ax, %gs",
            "mov %ax, %ss",
            "mov $0x18, %ax",
            "ltr %ax",
            gdt = in(reg) addr_of!(gdtr),
            out("eax") _,
            options(att_syntax)
        );
    }
    if !cpu_readback(directory)
        || !crate::interrupt::install_double_fault_task_gate()
        || !verify(directory)
    {
        if F5 {
            return false;
        }
        fail();
    }
    true

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
#[repr(C)]
pub struct ExceptionFrame {
    pub gs: u32,
    pub fs: u32,
    pub es: u32,
    pub ds: u32,
    pub edi: u32,
    pub esi: u32,
    pub ebp: u32,
    /// PUSHAD input ESP: address of the normalized vector, not interrupted ESP.
    pub pushad_esp: u32,
    pub ebx: u32,
