    pub eax: u32,
    pub vector: u32,
    pub error: u32,
    pub eip: u32,
    pub cs: u32,
    pub eflags: u32,
}

pub const FRAME_SIZE: usize = 68;
pub const VECTOR_OFFSET: usize = 48;
const _: () = {
    assert!(core::mem::size_of::<ExceptionFrame>() == FRAME_SIZE);
    assert!(core::mem::align_of::<ExceptionFrame>() == 4);
    assert!(core::mem::offset_of!(ExceptionFrame, gs) == 0);
    assert!(core::mem::offset_of!(ExceptionFrame, fs) == 4);
    assert!(core::mem::offset_of!(ExceptionFrame, es) == 8);
    assert!(core::mem::offset_of!(ExceptionFrame, ds) == 12);
    assert!(core::mem::offset_of!(ExceptionFrame, edi) == 16);
    assert!(core::mem::offset_of!(ExceptionFrame, esi) == 20);
    assert!(core::mem::offset_of!(ExceptionFrame, ebp) == 24);
    assert!(core::mem::offset_of!(ExceptionFrame, pushad_esp) == 28);
    assert!(core::mem::offset_of!(ExceptionFrame, ebx) == 32);
    assert!(core::mem::offset_of!(ExceptionFrame, edx) == 36);
    assert!(core::mem::offset_of!(ExceptionFrame, ecx) == 40);
    assert!(core::mem::offset_of!(ExceptionFrame, eax) == 44);
    assert!(core::mem::offset_of!(ExceptionFrame, vector) == VECTOR_OFFSET);
    assert!(core::mem::offset_of!(ExceptionFrame, error) == 52);
    assert!(core::mem::offset_of!(ExceptionFrame, eip) == 56);
    assert!(core::mem::offset_of!(ExceptionFrame, cs) == 60);
    assert!(core::mem::offset_of!(ExceptionFrame, eflags) == 64);

impl ExceptionFrame {
    /// #DF saved CS/EIP are architecturally undefined. Never report its origin.
    pub fn origin(&self) -> Option<u32> {
        if self.vector == 8 || frame_kind(self.vector) == FrameKind::Unsupported {
            None
        } else {
            Some(self.cs & 3)
        }
    }

    /// Scalar address arithmetic only; never dereference nonexistent SS/ESP.
    pub fn same_ring_esp(&self, prefix_address: u32) -> Option<u32> {
        if self.origin() == Some(0) {
            prefix_address.checked_add(FRAME_SIZE as u32)
        } else {
            None
        }
    }

    /// Synthetic decoder ONLY. Production fatal entry never calls this API.
    #[allow(dead_code)]
    pub fn synthetic_transition_tail(&self, words: &[u32]) -> Option<(u32, u32)> {
        if self.origin()? != 0 && words.len() == 2 {
            Some((words[0], words[1] & 0xffff))
        } else {
            None
        }
    }

//! F5 terminal CPL3 isolation proof: pure contract definitions.
//! One-shot Ring-3 entry followed by a kernel-owned exception report and halt.
//! No scheduler, syscalls, recovery, PAE/NX or general userland.
//! Target-only launcher/bridge/reporting must be verified separately from these
//! shared scalar contracts; passing host tests is not CPL3 hardware evidence.

pub use crate::memory::paging::f5_contract::*;

pub fn f5_saved_eflags_ok(observed: u32) -> bool {
    (observed & !F5_EFLAGS_AF_MASK) == (F5_SAVED_EFLAGS_AF0 & !F5_EFLAGS_AF_MASK)
}

pub fn f5_saved_selector_ok(raw: u32, expected: u16) -> bool {
    // CPU selector-slot padding (high 16 bits of the 32-bit pushed slot) is
    // recorded raw but never constrained; only the architectural low16 compares.
    (raw & 0xffff) == u32::from(expected)

#[unsafe(export_name = "f5_run_cpl3")]
#[unsafe(link_section = ".text.f4_contract")]
pub(crate) extern "C" fn run(scenario: u32) -> ! {
    unsafe {
        asm!("cli", "cld", options(nostack));
    }
    if !admit_f5(scenario) {
        f5_unsupported();
    }
    let directory = {
        let mut owner = OWNER.lock();
        let mut map = crate::memory::PAGE_MAP.lock();
        let mut fa = crate::memory::FRAME_ALLOC.lock();
        match map.as_mut() {
            Some(pm) => {
                if crate::memory::PAGING_ENABLED.load(Ordering::Acquire)
                    && prepare_f5_locked(&mut owner, pm, &mut fa, scenario)
                {
                    Some(pm.directory as u32)
                } else {
                    None
                }
            }
            _ => None,
        }
    };
    let Some(directory) = directory else {
        f5_unsupported();
    };
    if !crate::gdt_tss::install_f5(directory)
        || !crate::gdt_tss::verify(directory)
        || !crate::f5_gdt::install(directory)
        || !install_gates()
    {
        f5_unsupported();

let valid = {
    let mut owner = OWNER.lock();
    let map = crate::memory::PAGE_MAP.lock();
    let fa = crate::memory::FRAME_ALLOC.lock();
    map.as_ref()
        .is_some_and(|pm| seal_f5_locked(&mut owner, pm, &fa))
};
if !valid || !crate::f5_gdt::verify(directory) {
    f5_unsupported();
}
let Some(row) = f5_row(scenario) else {
    f5_unsupported();
};
unsafe {
    let expect = addr_of_mut!(f5_expect).cast::<u32>();
    for (i, value) in [
        scenario,
        row.vector,
        row.error,
        row.fault_eip,
        row.cr2,
        directory,
        row.entry,
    ]
    .iter()
    .enumerate()
    {
        write_volatile(expect.add(i), *value);
    }
    // Same PIC mask protocol as existing IRQ controller setup, no allocation
    // or port ownership change. IF remains0 and every fixture is one vCPU.
    crate::io::ports::lockfree_outb(0x21, 0xff);
    crate::io::ports::lockfree_outb(0xa1, 0xff);
}
f5_iret()

